int _purchaseOrderEstimateSize(
  PurchaseOrder object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  {
    final value = object.notes;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.poNumber.length * 3;
  bytesCount += 3 + object.status.length * 3;
  bytesCount += 3 + object.supplierName.length * 3;
  {
    final value = object.supplierTpin;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  return bytesCount;
}

void _purchaseOrderSerialize(
  PurchaseOrder object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeDateTime(offsets[0], object.approvedAt);
  writer.writeDateTime(offsets[1], object.createdAt);
  writer.writeDouble(offsets[2], object.discountAmount);
  writer.writeDateTime(offsets[3], object.expectedDeliveryDate);
  writer.writeString(offsets[4], object.notes);
  writer.writeString(offsets[5], object.poNumber);
  writer.writeString(offsets[6], object.status);
  writer.writeLong(offsets[7], object.storeId);
  writer.writeDouble(offsets[8], object.subtotal);
  writer.writeLong(offsets[9], object.supplierId);
  writer.writeString(offsets[10], object.supplierName);
  writer.writeString(offsets[11], object.supplierTpin);
  writer.writeDouble(offsets[12], object.taxAmount);
  writer.writeDouble(offsets[13], object.totalAmount);
}

