  object.createdAt = reader.readDateTime(offsets[1]);
  object.discountAmount = reader.readDouble(offsets[2]);
  object.expectedDeliveryDate = reader.readDateTimeOrNull(offsets[3]);
  object.id = id;
  object.notes = reader.readStringOrNull(offsets[4]);
  object.poNumber = reader.readString(offsets[5]);
  object.status = reader.readString(offsets[6]);
  object.storeId = reader.readLong(offsets[7]);
  object.subtotal = reader.readDouble(offsets[8]);
  object.supplierId = reader.readLongOrNull(offsets[9]);
  object.supplierName = reader.readString(offsets[10]);
  object.supplierTpin = reader.readStringOrNull(offsets[11]);
  object.taxAmount = reader.readDouble(offsets[12]);
