int _purchaseInvoiceEstimateSize(
  PurchaseInvoice object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.invoiceNumber.length * 3;
  bytesCount += 3 + object.paymentStatus.length * 3;
  bytesCount += 3 + object.poNumber.length * 3;
  {
    final value = object.supplierInvoiceNumber;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.supplierName.length * 3;
  return bytesCount;
}

