  writer.writeDouble(offsets[1], object.balanceDue);
  writer.writeDateTime(offsets[2], object.createdAt);
  writer.writeDateTime(offsets[3], object.dueDate);
  writer.writeString(offsets[4], object.invoiceNumber);
  writer.writeString(offsets[5], object.paymentStatus);
  writer.writeString(offsets[6], object.poNumber);
  writer.writeString(offsets[7], object.supplierInvoiceNumber);
  writer.writeString(offsets[8], object.supplierName);
  writer.writeDouble(offsets[9], object.totalAmount);
}

