int _expenseEstimateSize(
  Expense object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.branch.length * 3;
  bytesCount += 3 + object.category.length * 3;
  bytesCount += 3 + object.expenseNumber.length * 3;
  {
    final value = object.notes;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.paymentAccountName.length * 3;
  {
    final value = object.receiptImagePath;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  {
    final value = object.recordedBy;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  {
    final value = object.referenceNumber;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  return bytesCount;
}

void _expenseSerialize(
  Expense object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeDouble(offsets[0], object.amount);
  writer.writeString(offsets[1], object.branch);
  writer.writeString(offsets[2], object.category);
  writer.writeDateTime(offsets[3], object.createdAt);
  writer.writeDateTime(offsets[4], object.expenseDate);
  writer.writeString(offsets[5], object.expenseNumber);
  writer.writeString(offsets[6], object.notes);
  writer.writeLong(offsets[7], object.paymentAccountId);
  writer.writeString(offsets[8], object.paymentAccountName);
  writer.writeString(offsets[9], object.receiptImagePath);
  writer.writeString(offsets[10], object.recordedBy);
  writer.writeString(offsets[11], object.referenceNumber);
}

