  writer.writeLong(offsets[2], object.fromAccountId);
  writer.writeString(offsets[3], object.fromAccountName);
  writer.writeString(offsets[4], object.reference);
  writer.writeLong(offsets[5], object.toAccountId);
  writer.writeString(offsets[6], object.toAccountName);
  writer.writeDateTime(offsets[7], object.transferDate);
  writer.writeString(offsets[8], object.transferNumber);
