int _cashShiftEstimateSize(
  CashShift object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.branchName.length * 3;
  {
    final value = object.cashierId;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.cashierName.length * 3;
  {
    final value = object.notes;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.shiftNumber.length * 3;
  bytesCount += 3 + object.status.length * 3;
  bytesCount += 3 + object.terminalId.length * 3;
  return bytesCount;
}

void _cashShiftSerialize(
  CashShift object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeDouble(offsets[0], object.actualClosingCash);
  writer.writeString(offsets[1], object.branchName);
  writer.writeDouble(offsets[2], object.cashDeposits);
  writer.writeDouble(offsets[3], object.cashExpenses);
  writer.writeDouble(offsets[4], object.cashReceived);
  writer.writeDouble(offsets[5], object.cashRefunds);
  writer.writeDouble(offsets[6], object.cashSales);
  writer.writeDouble(offsets[7], object.cashVariance);
  writer.writeDouble(offsets[8], object.cashWithdrawals);
  writer.writeString(offsets[9], object.cashierId);
  writer.writeString(offsets[10], object.cashierName);
  writer.writeDateTime(offsets[11], object.closingTime);
  writer.writeDateTime(offsets[12], object.createdAt);
  writer.writeDouble(offsets[13], object.expectedClosingCash);
  writer.writeString(offsets[14], object.notes);
  writer.writeDouble(offsets[15], object.openingCash);
  writer.writeDateTime(offsets[16], object.openingTime);
  writer.writeString(offsets[17], object.shiftNumber);
  writer.writeString(offsets[18], object.status);
  writer.writeString(offsets[19], object.terminalId);
}

CashShift _cashShiftDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = CashShift();
  object.actualClosingCash = reader.readDouble(offsets[0]);
  object.branchName = reader.readString(offsets[1]);
  object.cashDeposits = reader.readDouble(offsets[2]);
  object.cashExpenses = reader.readDouble(offsets[3]);
  object.cashReceived = reader.readDouble(offsets[4]);
  object.cashRefunds = reader.readDouble(offsets[5]);
  object.cashSales = reader.readDouble(offsets[6]);
  object.cashVariance = reader.readDouble(offsets[7]);
  object.cashWithdrawals = reader.readDouble(offsets[8]);
  object.cashierId = reader.readStringOrNull(offsets[9]);
  object.cashierName = reader.readString(offsets[10]);
  object.closingTime = reader.readDateTimeOrNull(offsets[11]);
  object.createdAt = reader.readDateTime(offsets[12]);
  object.expectedClosingCash = reader.readDouble(offsets[13]);
  object.id = id;
  object.notes = reader.readStringOrNull(offsets[14]);
  object.openingCash = reader.readDouble(offsets[15]);
  object.openingTime = reader.readDateTime(offsets[16]);
  object.shiftNumber = reader.readString(offsets[17]);
  object.status = reader.readString(offsets[18]);
  object.terminalId = reader.readString(offsets[19]);
