int _refundTransactionEstimateSize(
  RefundTransaction object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  {
    final value = object.authorizedBy;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.reason.length * 3;
  bytesCount += 3 + object.refundNumber.length * 3;
  bytesCount += 3 + object.refundType.length * 3;
  {
    final value = object.saleTransactionUuid;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  return bytesCount;
}

void _refundTransactionSerialize(
  RefundTransaction object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeDouble(offsets[0], object.amount);
  writer.writeString(offsets[1], object.authorizedBy);
  writer.writeDateTime(offsets[2], object.createdAt);
  writer.writeString(offsets[3], object.reason);
  writer.writeDateTime(offsets[4], object.refundDate);
  writer.writeString(offsets[5], object.refundNumber);
  writer.writeString(offsets[6], object.refundType);
  writer.writeString(offsets[7], object.saleTransactionUuid);
}

RefundTransaction _refundTransactionDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = RefundTransaction();
  object.amount = reader.readDouble(offsets[0]);
  object.authorizedBy = reader.readStringOrNull(offsets[1]);
  object.createdAt = reader.readDateTime(offsets[2]);
  object.id = id;
  object.reason = reader.readString(offsets[3]);
  object.refundDate = reader.readDateTime(offsets[4]);
  object.refundNumber = reader.readString(offsets[5]);
  object.refundType = reader.readString(offsets[6]);
  object.saleTransactionUuid = reader.readStringOrNull(offsets[7]);
  return object;
}

