int _posTerminalEstimateSize(
  PosTerminal object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  {
    final value = object.assignedCashierId;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  {
    final value = object.assignedCashierName;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.branchCode.length * 3;
  bytesCount += 3 + object.branchName.length * 3;
  {
    final value = object.deviceIp;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.digitaxBhfId.length * 3;
  bytesCount += 3 + object.name.length * 3;
  {
    final value = object.serialNumber;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.status.length * 3;
  bytesCount += 3 + object.terminalCode.length * 3;
  return bytesCount;
}

void _posTerminalSerialize(
