  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeString(offsets[0], object.assignedCashierId);
  writer.writeString(offsets[1], object.assignedCashierName);
  writer.writeString(offsets[2], object.branchCode);
  writer.writeString(offsets[3], object.branchName);
  writer.writeDateTime(offsets[4], object.createdAt);
  writer.writeString(offsets[5], object.deviceIp);
  writer.writeString(offsets[6], object.digitaxBhfId);
  writer.writeDateTime(offsets[7], object.lastActive);
  writer.writeString(offsets[8], object.name);
  writer.writeDouble(offsets[9], object.salesToday);
  writer.writeString(offsets[10], object.serialNumber);
  writer.writeString(offsets[11], object.status);
  writer.writeString(offsets[12], object.terminalCode);
}

PosTerminal _posTerminalDeserialize(
  Id id,
