  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = PosTerminal();
  object.assignedCashierId = reader.readStringOrNull(offsets[0]);
  object.assignedCashierName = reader.readStringOrNull(offsets[1]);
  object.branchCode = reader.readString(offsets[2]);
