  object.createdAt = reader.readDateTime(offsets[4]);
  object.deviceIp = reader.readStringOrNull(offsets[5]);
  object.digitaxBhfId = reader.readString(offsets[6]);
  object.id = id;
  object.lastActive = reader.readDateTime(offsets[7]);
  object.name = reader.readString(offsets[8]);
  object.salesToday = reader.readDouble(offsets[9]);
  object.serialNumber = reader.readStringOrNull(offsets[10]);
  object.status = reader.readString(offsets[11]);
